MATCH (s:Set {set_num: '71012-18'})
MATCH (s)-[:HAS_INVENTORY]->(inv:Inventory)
WITH s, inv
ORDER BY inv.version DESC
WITH s, head(collect(inv)) AS currentInv

// Direct parts from the set's own inventory (excluding spare)
OPTIONAL MATCH (currentInv)-[hp:HAS_PART]->(p:Part)
WHERE hp.is_spare = false
WITH s, currentInv, sum(hp.qty) AS directQty

// Nested sets and minifigs quantities from the set's own inventory
OPTIONAL MATCH (currentInv)-[cs:CONTAINS_SET]->(nestedSet:Set)
OPTIONAL MATCH (currentInv)-[cm:CONTAINS_MINIFIG]->(mf:Minifig)
WITH s, currentInv, directQty,
     sum(coalesce(cs.qty, 0)) AS nestedSetQty,
     sum(coalesce(cm.qty, 0)) AS minifigQty

// Total quantity = direct + nested sets + minifigs (each nested item counts as 1 unit here,
// but the question asks for percentage of total part quantity, so we need to explode nested contents)
// Actually, the question asks: "percentage of the total part quantity ... comes from its nested sets and minifigs
// rather than from the parts listed directly in its own inventory"
// So we need to compute total part quantity at all levels, and the part quantity contributed by nested sets/minifigs.

// Let's compute recursively using a path explosion approach.
// We'll use a variable-length pattern to find all paths from the set's inventory to parts,
// multiplying quantities along the way.

// First, get the current inventory id
WITH s, currentInv, directQty, nestedSetQty, minifigQty
MATCH path = (currentInv)-[:CONTAINS_SET|CONTAINS_MINIFIG*0..]->(inv2:Inventory)
WHERE ALL(r IN relationships(path) WHERE true) // no filter needed, all relationships are contains
WITH s, currentInv, directQty, nestedSetQty, minifigQty, path, inv2
// For each inventory in the path, get its parts
OPTIONAL MATCH (inv2)-[hp:HAS_PART]->(p:Part)
WHERE hp.is_spare = false
WITH s, currentInv, directQty, nestedSetQty, minifigQty, path, inv2, hp, p
// Compute the multiplier for this path: product of quantities along the path
WITH s, currentInv, directQty, nestedSetQty, minifigQty, path, inv2, hp, p,
     reduce(mult = 1, r IN relationships(path) | mult * r.qty) AS pathMult
WITH s, currentInv, directQty, nestedSetQty, minifigQty,
     sum(pathMult * hp.qty) AS totalPartsFromAllLevels

// Now compute parts from nested sets and minifigs (i.e., not direct)
// We can compute total parts from nested sets and minifigs by subtracting direct parts
// But we need to be careful: direct parts are from the set's own inventory only.
// The total parts from all levels includes direct parts plus parts from nested sets/minifigs.
// So nested/minifig parts = totalPartsFromAllLevels - directQty

WITH s, directQty, totalPartsFromAllLevels,
     (totalPartsFromAllLevels - directQty) AS nestedMinifigParts
RETURN round(100.0 * nestedMinifigParts / totalPartsFromAllLevels, 2) AS percentage
